  Label Metric(FlowLayoutPanel parent,string title,string value,int width){var tile=Tile(title,"",width,110);var label=new Label{Text=value,ForeColor=accent,Font=new Font("Segoe UI",25,FontStyle.Bold),Location=new Point(14,48),Size=new Size(width-28,48)};tile.Controls.Add(label);label.BringToFront();parent.Controls.Add(tile);return label;}
  async Task SampleResources(bool gpu){if(sampling)return;sampling=true;try{var sample=await Task.Run(()=>sampler.Sample(gpu));if(double.IsNaN(sample.Cpu)){await Task.Delay(300);var follow=await Task.Run(()=>sampler.Sample(false));sample.Cpu=follow.Cpu;sample.Ram=follow.Ram;}if(IsDisposed)return;cpuValue.Text=double.IsNaN(sample.Cpu)?"Sampling...":sample.Cpu.ToString("0.0")+"%";ramValue.Text=sample.Ram.ToString("0")+"%";if(gpu){gpuValue.Text=double.IsNaN(sample.Gpu)?"Unavailable":sample.Gpu.ToString("0")+"%";gpuDetail.Text=sample.GpuDetails+"  /  "+sample.Time.ToString("T");}samples.Add(sample);if(samples.Count>120)samples.RemoveAt(0);resourceChart.Values=samples.ToArray();resourceChart.Invalidate();RefreshDashboardCounts();}catch(Exception e){Status("Resource scan: "+e.Message);}finally{sampling=false;}}
  void RefreshDashboardCounts(){if(dashboardCounts==null)return;dashboardCounts.Text=journal.Items.Count(x=>x.Status!="Restored")+" outstanding journal entries   /   "+Directory.GetFiles(presetsFolder,"*.json").Length+" saved profiles   /   "+(journal.Items.Any(x=>x.SessionId!=null&&x.Status!="Restored")?"Session recovery available":"No session changes active");}
  void BuildCatalog(){var p=Page("Optimizations","Know what each switch does.","Direct controls change this account and support Recovery. Guided controls open the supported UI.\r\nOrange = HIGH potential. Yellow = MEDIUM. Blue = LOW. Potential is not a measured gain.");var r=Row();r.Controls.Add(Inline("Search",60));search=new TextBox{Width=290,BackColor=panel,ForeColor=ink,Margin=new Padding(0,6,12,0),AccessibleName="Search optimization catalog"};category=Combo(new[]{"All categories","Windows","Power","Display","Input","Storage","Network","Drivers","Games","Not included"},235);r.Controls.Add(search);r.Controls.Add(category);r.Controls.Add(Button("Refresh states",PopulateCatalog));p.Controls.Add(r);var b=Row();b.Controls.Add(Button("Apply selected direct controls",ApplyCatalogSelection));b.Controls.Add(Button("Windows controls",delegate{ShowPage("Windows tuning");}));p.Controls.Add(b);catalogCards=new FlowLayoutPanel{Width=870,AutoSize=true,FlowDirection=FlowDirection.LeftToRight,WrapContents=true,Margin=new Padding(0)};p.Controls.Add(catalogCards);search.TextChanged+=delegate{PopulateCatalog();};category.SelectedIndexChanged+=delegate{PopulateCatalog();};PopulateCatalog();}
  void PopulateCatalog(){catalogCards.SuspendLayout();foreach(Control child in catalogCards.Controls.Cast<Control>().ToArray())child.Dispose();catalogCards.Controls.Clear();tweakStatus.Clear();foreach(var tweak in tweaks.Where(x=>(category.SelectedIndex==0||x.Category==category.Text)&&(string.IsNullOrWhiteSpace(search.Text)||(x.Name+" "+x.Description).IndexOf(search.Text,StringComparison.OrdinalIgnoreCase)>=0))){var t=tweak;var tile=Tile(t.Name,t.Description,418,350);var stateLabel=new Label{Text=t.Mode.ToUpperInvariant()+"  /  "+t.Read(),ForeColor=t.Mode=="Excluded"?Color.FromArgb(230,179,117):accent,Location=new Point(16,151),Size=new Size(386,38)};tile.Controls.Add(stateLabel);tweakStatus[t.Id]=stateLabel;if(t.Direct){var check=new CheckBox{Text="Select",Checked=selectedTweaks.Contains(t.Id),ForeColor=ink,Location=new Point(16,196),Size=new Size(78,32)};check.CheckedChanged+=delegate{if(check.Checked)selectedTweaks.Add(t.Id);else selectedTweaks.Remove(t.Id);};tile.Controls.Add(check);var apply=Button("Apply",delegate{ApplyCatalogTweak(t);});apply.SetBounds(98,193,91,36);tile.Controls.Add(apply);var undo=Button("Undo",delegate{UndoCatalogTweak(t);});undo.SetBounds(202,193,91,36);tile.Controls.Add(undo);}else if(t.Mode=="Guided"){var open=Button("Open settings / guide",delegate{OpenDestination(t.Destination);});open.Location=new Point(16,191);tile.Controls.Add(open);}ImpactBadges(tile,t);catalogCards.Controls.Add(tile);}catalogCards.ResumeLayout();}
  void ApplyCatalogTweak(Tweak t){t.Apply(journal);PopulateCatalog();Status(t.Name+": requested value applied; check the supported UI if a restart is needed.");}
  void UndoCatalogTweak(Tweak t){var c=journal.Items.LastOrDefault(x=>x.Status!="Restored"&&(t.Path!=null?x.Kind=="Registry"&&x.Target==t.Path&&x.Name==t.ValueName:x.Kind=="Power"&&x.After==t.Destination));if(c==null)throw new Exception("No outstanding FramePilot change for this control.");journal.Restore(c);PopulateCatalog();Status(t.Name+": original restored.");}
  void OpenDestination(string target){if(target=="dfrgui.exe")target=Path.Combine(Environment.SystemDirectory,target);Open(target);}
  void ApplyCatalogSelection(){var selected=tweaks.Where(x=>x.Direct&&selectedTweaks.Contains(x.Id)).ToArray();if(selected.Length==0)throw new Exception("Select at least one direct control.");if(selected.Count(x=>x.Category=="Power")>1)throw new Exception("Choose one power plan, not both.");int start=journal.Items.Count;try{foreach(var t in selected)t.Apply(journal);}catch(Exception e){var failures=new List<string>();foreach(var c in journal.Items.Skip(start).Reverse().ToArray())try{journal.Restore(c);}catch(Exception failure){failures.Add(failure.Message);}PopulateCatalog();throw new Exception("Batch interrupted: "+e.Message+". Rollback: "+(failures.Count==0?"completed":string.Join("; ",failures)));}PopulateCatalog();Status("Selected direct controls applied. Original values are in Recovery.");}
  void BuildLibrary(){var p=Page("Game library","Five games. Your profiles.","Original FramePilot cards, with local presets and your choice of official launcher shortcut.\r\nLoading a profile fills the editor; it never applies settings or launches a game automatically.");var cards=new FlowLayoutPanel{Width=870,AutoSize=true,WrapContents=true};string[] descriptions={"Competitive clarity / Reflex / input","Quality controls / DLSS / frame cap","Title-specific checklist / shader warm-up","World distance / simulation / frame pacing","Map consistency / visibility / frame times"};for(int i=0;i<game.Items.Count;i++){string name=game.Items[i].ToString();var tile=Tile(name,descriptions[i],418,160);var edit=Button("Configure",delegate{game.SelectedItem=name;ShowPage("Game profiles");});edit.Location=new Point(16,108);tile.Controls.Add(edit);var launch=Button("Launch",delegate{LaunchSaved(name);});launch.Location=new Point(135,108);tile.Controls.Add(launch);var set=Button("Link launcher",delegate{LinkLauncher(name);});set.Location=new Point(245,108);tile.Controls.Add(set);cards.Controls.Add(tile);}p.Controls.Add(cards);p.Controls.Add(Note("STARTER & SAVED PROFILES",26));savedProfiles=new ListBox{Width=850,Height=125,BackColor=panel,ForeColor=ink};p.Controls.Add(savedProfiles);var r=Row();r.Controls.Add(Button("Refresh profiles",RefreshProfiles));r.Controls.Add(Button("Load selected profile",delegate{var profile=savedProfiles.SelectedItem as GamePreset;if(profile==null)throw new Exception("Select a saved profile.");LoadPreset(profile);}));r.Controls.Add(Button("Import JSON",delegate{using(var d=new OpenFileDialog{Filter="FramePilot preset|*.json"})if(d.ShowDialog()==DialogResult.OK)LoadPreset(Presets.Load(d.FileName));}));p.Controls.Add(r);RefreshProfiles();}
  string LauncherFile(string name){return Path.Combine(data,"launcher-"+Array.IndexOf(game.Items.Cast<object>().Select(x=>x.ToString()).ToArray(),name)+".txt");}
  void LinkLauncher(string name){using(var d=new OpenFileDialog{Filter="Official launcher or shortcut|*.exe;*.lnk",Title="Choose "+name+"'s official launcher or shortcut"})if(d.ShowDialog()==DialogResult.OK){Journal.Atomic(LauncherFile(name),Encoding.UTF8.GetBytes(d.FileName));Status("Launcher link saved. It will run only when you choose Launch.");}}
  void LaunchSaved(string name){string f=LauncherFile(name);if(!File.Exists(f))throw new Exception("Link this game's official launcher or shortcut first, so its anti-cheat initializes normally.");string path=File.ReadAllText(f);if(!File.Exists(path)||!new[]{".exe",".lnk"}.Contains(Path.GetExtension(path),StringComparer.OrdinalIgnoreCase))throw new Exception("Launcher link is no longer valid; link it again.");Open(path);Status("Official launcher requested. No game process settings were changed.");}
  void AddPresetControls(){var p=(FlowLayoutPanel)pages["Game profiles"];var lockNotice=Note("External config writes are controlled by the lock in Session mode (ON by default).",30);p.Controls.Add(lockNotice);p.Controls.SetChildIndex(lockNotice,2);var r=Row();presetName=new TextBox{Text="My balanced profile",Width=235,BackColor=panel,ForeColor=ink,AccessibleName="Preset name",Margin=new Padding(0,8,12,0)};r.Controls.Add(presetName);r.Controls.Add(Button("Save local preset",delegate{var profile=CapturePreset();Presets.Save(Path.Combine(presetsFolder,Guid.NewGuid().ToString("N")+".json"),profile);RefreshProfiles();Status("Saved locally. Load it from Game library.");}));r.Controls.Add(Button("Export preset JSON",delegate{var profile=CapturePreset();profile.ConfigPath=null;using(var d=new SaveFileDialog{FileName="framepilot-preset.json",Filter="FramePilot preset|*.json"})if(d.ShowDialog()==DialogResult.OK)Presets.Save(d.FileName,profile);}));p.Controls.Add(r);p.Controls.SetChildIndex(r,4);}
  GamePreset CapturePreset(){var p=new GamePreset{Game=game.Text,Name=presetName.Text.Trim(),ConfigPath=configPath,Quality=quality.SelectedIndex,Cap=(int)cap.Value,Render=(int)render.Value,Simulation=(int)simulation.Value,Resolution=resolution.SelectedIndex,Vsync=vsync.Checked,DisableFrameGen=noFrameGen.Checked,DisableNanite=noNanite.Checked,Graphics=graphicOptions.ToDictionary(x=>x.Key,x=>x.Value.SelectedIndex)};p.Validate();return p;}
  void LoadPreset(GamePreset p){p.Validate();game.SelectedItem=p.Game;quality.SelectedIndex=p.Quality;cap.Value=p.Cap;render.Value=p.Render;simulation.Value=p.Simulation;resolution.SelectedIndex=p.Resolution;vsync.Checked=p.Vsync;noFrameGen.Checked=p.DisableFrameGen;noNanite.Checked=p.DisableNanite;foreach(var kv in p.Graphics)graphicOptions[kv.Key].SelectedIndex=kv.Value;presetName.Text=p.Name;if(p.ConfigPath!=null){configPath=p.ConfigPath;gamePath.Text=configPath;}ClearPreview();ShowPage("Game profiles");Status("Preset loaded into editor only. Preview before applying.");}
  void RefreshProfiles(){savedProfiles.Items.Clear();var assembly=System.Reflection.Assembly.GetExecutingAssembly();foreach(string resource in assembly.GetManifestResourceNames().Where(x=>x.StartsWith("starter-"))){using(var reader=new StreamReader(assembly.GetManifestResourceStream(resource))){var preset=new System.Web.Script.Serialization.JavaScriptSerializer().Deserialize<GamePreset>(reader.ReadToEnd());preset.Validate();savedProfiles.Items.Add(preset);}}string bundled=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"presets");var paths=Directory.GetFiles(presetsFolder,"*.json").Concat(assembly.GetManifestResourceNames().Any(x=>x.StartsWith("starter-"))?new string[0]:(Directory.Exists(bundled)?Directory.GetFiles(bundled,"*.json"):new string[0]));foreach(var path in paths)try{savedProfiles.Items.Add(Presets.Load(path));}catch{savedProfiles.Items.Add("Unreadable preset: "+Path.GetFileName(path));}}
  void BuildSessions(){var p=Page("Session mode","Tune before play. Restore afterward.","A session groups temporary Windows changes under one recovery scope. It does not hook into\r\ngames or watch for game launches. End the session here, or exit FramePilot normally to restore.");sessionLabel=Note("",50);p.Controls.Add(sessionLabel);sessionRecord=Check("Temporarily disable Windows game recording",false);sessionPower=Check("Temporarily select High performance (A/B experiment)",false);p.Controls.Add(Note("Sessions request Windows Game Mode; matching settings are left as they are.",30));p.Controls.Add(sessionRecord);p.Controls.Add(sessionPower);var r=Row();r.Controls.Add(Button("Start session",StartSession));r.Controls.Add(Button("End session / recover",delegate{EndSession(true);}));p.Controls.Add(r);
   lockConfigEdits=Check("Lock external game-config edits (use in-game controls only)",true);string settings=Path.Combine(data,"config-edit-lock.txt");if(File.Exists(settings))lockConfigEdits.Checked=File.ReadAllText(settings)!="off";lockConfigEdits.CheckedChanged+=delegate{Journal.Atomic(settings,Encoding.UTF8.GetBytes(lockConfigEdits.Checked?"on":"off"));ClearPreview();};p.Controls.Add(lockConfigEdits);
   p.Controls.Add(Note("ANTI-CHEAT BOUNDARY",28));p.Controls.Add(Note("The config-edit lock starts ON in v2. It blocks direct config apply and restore until you turn it off.\r\nChecklists and profile previews remain available. This reduces external game-file changes; it is\r\nnot a guarantee against bans. Neither mode is certified by Riot, Epic, Activision or BattlEye.\r\n\r\nFramePilot never changes game process priority/affinity, game memory, input, executables,\r\nanti-cheat services or security settings. There is no injected overlay, capture hook or driver.\r\nBackground-app priority actions stay limited to the optional allowlist on their own page.\r\n\r\nIf a crash interrupts a session, its changes remain tagged in Recovery for the next launch.\r\nFor minimal software running while you play, use in-game controls and exit FramePilot.",220));UpdateSessionLabel();}
  void UpdateSessionLabel(){sessionLabel.Text=journal.Items.Any(x=>x.SessionId!=null&&x.Status!="Restored")?"SESSION CHANGES ACTIVE / recovery available":"NO SESSION CHANGES ACTIVE";}
  void StartSession(){if(journal.Items.Any(x=>x.SessionId!=null&&x.Status!="Restored"))throw new Exception("End or recover the existing session first.");journal.Scope=Guid.NewGuid().ToString("N");try{tweaks.First(x=>x.Id=="game-mode").Apply(journal);if(sessionRecord.Checked){tweaks.First(x=>x.Id=="dvr").Apply(journal);tweaks.First(x=>x.Id=="capture").Apply(journal);}if(sessionPower.Checked)tweaks.First(x=>x.Id=="high-power").Apply(journal);}catch{EndSession(false);throw;}finally{journal.Scope=null;UpdateSessionLabel();}Status("Session preferences applied. Existing values that already match need no recovery entry.");}
  void EndSession(bool show){var errors=new List<string>();foreach(var c in journal.Items.Where(x=>x.SessionId!=null&&x.Status!="Restored").Reverse().ToArray())try{journal.Restore(c);}catch(Exception e){errors.Add(c.Name+": "+e.Message);}if(sessionLabel!=null)UpdateSessionLabel();if(show){Status(errors.Count==0?"Session restored.":"Session conflicts remain in Recovery.");if(errors.Count>0)MessageBox.Show(this,string.Join("\r\n",errors),"Session recovery");}}
  void BuildStartup(){var p=Page("Startup apps","Less to start with.","Read the current user's Run entries. Only recognized optional apps can be disabled here.\r\nDisabling removes their Run entry with a typed backup; it does not close the running app.");startupList=new CheckedListBox{Width=850,Height=280,BackColor=panel,ForeColor=ink,CheckOnClick=true};p.Controls.Add(startupList);startupList.ItemCheck+=delegate(object sender,ItemCheckEventArgs e){var item=startupList.Items[e.Index] as StartupItem;if(item!=null&&!item.Eligible){e.NewValue=CheckState.Unchecked;Status("Protected or unrecognized startup entry. Use Windows Settings to review it.");}};var r=Row();r.Controls.Add(Button("Scan startup entries",ScanStartup));r.Controls.Add(Button("Disable selected entries",DisableStartup));r.Controls.Add(Button("Windows startup settings",delegate{Open("ms-settings:startupapps");}));p.Controls.Add(r);p.Controls.Add(Note("Optional entries include Discord, Steam, Epic, OneDrive, CurseForge, Blitz and Overwolf.\r\nBoth entry name and executable path must match. RunOnce, machine-wide entries, services,\r\nscheduled tasks and startup folders are untouched. Packaged apps use Windows Settings.\r\nRestore disabled entries in Recovery. Re-enabling does not execute their stored commands.\r\nAn app can recreate its own startup entry; rescan after updates.",118));}
  void ScanStartup(){startupList.Items.Clear();var entries=Startup.Read();foreach(var item in entries.Where(x=>x.Eligible))startupList.Items.Add(item);if(protectedStartup!=null)protectedStartup.Text=string.Join("\r\n",entries.Where(x=>!x.Eligible).Select(x=>x.Name+" — managed in Windows to preserve security, devices or unrecognized apps."));if(disableStartupButton!=null){disableStartupButton.Enabled=false;disableStartupButton.Text="Disable selected (0)";}Status(startupList.Items.Count+" optional startup apps available. Select a checkbox to enable Disable.");}
  void DisableStartup(){var errors=new List<string>();int done=0;foreach(StartupItem item in startupList.CheckedItems)try{journal.RemoveStartup(item.Name,item.Command);done++;}catch(Exception e){errors.Add(e.Message);}ScanStartup();Status(done+" startup entries disabled; "+errors.Count+" skipped.");if(errors.Count>0)MessageBox.Show(this,string.Join("\r\n",errors),"Startup results");}
  void BuildMaintenance(){var p=Page("Maintenance","Clean with a way back.","Conservative temp-file quarantine: selected files are moved into FramePilot recovery storage.\r\nThis tidies the temp folder but does not reclaim disk space until backups are removed manually.");tempList=new CheckedListBox{Width=850,Height=245,BackColor=panel,ForeColor=ink,CheckOnClick=true};p.Controls.Add(tempList);var r=Row();r.Controls.Add(Button("Scan old temp files",ScanTemp));r.Controls.Add(Button("Quarantine selected",QuarantineTemp));r.Controls.Add(Button("Open Windows storage",delegate{Open("ms-settings:storagesense");}));p.Controls.Add(r);var r2=Row();r2.Controls.Add(Button("Drive capacity report",delegate{diagnosticText.Text=DiskReport();ShowPage("Diagnostics");}));r2.Controls.Add(Button("Windows optimize drives",delegate{OpenDestination("dfrgui.exe");}));p.Controls.Add(r2);p.Controls.Add(Note("Only .tmp, .log and .dmp files directly inside your temp folder, older than 7 days, at most 50 MB\r\neach. Scan limit: first 5,000 files / 200 eligible results. No recursion into app folders. Linked,\r\nread-only, changed or in-use files are skipped. Each move is journaled before it happens.\r\n\r\nGame saves, Downloads, Steam Workshop, shader caches, browser data, event logs and\r\ncrash dumps outside that temp scope are untouched. Cleanup is not an FPS optimization.\r\nThere is no auto-clean schedule and no automatic deletion of the recovery copies.",166));}
  void ScanTemp(){tempList.Items.Clear();foreach(var item in Maintenance.Scan(tempRoot))tempList.Items.Add(item);Status(tempList.Items.Count+" eligible files; none selected. Quarantine preserves their disk usage.");}
  void QuarantineTemp(){var errors=new List<string>();int done=0;foreach(TempItem item in tempList.CheckedItems)try{journal.Quarantine(item,tempRoot);done++;}catch(Exception e){errors.Add(Path.GetFileName(item.Path)+": "+e.Message);}ScanTemp();Status(done+" files quarantined; "+errors.Count+" skipped. Recovery can move them back.");if(errors.Count>0)MessageBox.Show(this,string.Join("\r\n",errors),"Maintenance results");}
  static string DiskReport(){var b=new StringBuilder("DRIVE CAPACITY / no maintenance performed\r\n\r\n");foreach(var drive in DriveInfo.GetDrives())try{if(drive.IsReady)b.AppendLine(string.Format("{0}  {1}  {2:0.0} GB free of {3:0.0} GB ({4:0.0}% free)",drive.Name,drive.DriveType,drive.AvailableFreeSpace/1e9,drive.TotalSize/1e9,100.0*drive.AvailableFreeSpace/drive.TotalSize));}catch(Exception e){b.AppendLine(drive.Name+": "+e.Message);}return b.ToString();}
  void BuildDiagnostics(){var p=Page("Diagnostics","Inspect before you intervene.","Read-only capability checks, drive capacity and bounded network tests. Unknown states stay\r\nunknown; a successful access check is not an anti-cheat certification or a performance result.");var r=Row();r.Controls.Add(Button("Check settings access",CheckAccess));r.Controls.Add(Button("Drive capacity",delegate{diagnosticText.Text=DiskReport();}));r.Controls.Add(Button("Export this report",delegate{SaveText(diagnosticText.Text,"framepilot-diagnostics.txt");}));p.Controls.Add(r);var net=Row();pingHost=new TextBox{Text=NetworkResult.Gateway(),Width=230,BackColor=panel,ForeColor=ink,Margin=new Padding(0,8,12,0),AccessibleName="Ping hostname or IP"};net.Controls.Add(pingHost);net.Controls.Add(Button("Test 10 pings",async delegate{if(busy)return;busy=true;string host=pingHost.Text.Trim();Status("Measuring ICMP round trips...");try{var result=await NetworkResult.Measure(host);diagnosticText.Text="ICMP target: "+host+"\r\n"+result+"\r\n\r\nA local gateway isolates part of the local network path. A remote host adds routing.\r\nICMP can be blocked or deprioritized; packet loss here does not prove game-packet loss.\r\nThis is not a game-server ping or mouse-to-photon latency measurement.";Status("Network test finished; no network settings changed.");}catch(Exception e){Status(e.Message);}finally{busy=false;}}));p.Controls.Add(net);p.Controls.Add(Note("Target starts at a discovered IPv4 gateway; it may be a VPN or virtual adapter. Edit as needed.",28));diagnosticText=Box(350);p.Controls.Add(diagnosticText);p.Controls.Add(Note("Source research and compatibility decisions are included in RESEARCH-v2.md beside the app.\r\nKeep your installed driver version stable while comparing runs; make one change at a time.",65));}
  void CheckAccess(){var b=new StringBuilder("FRAMEPILOT 3 / ACCESS AUDIT / "+DateTime.Now.ToString("s")+"\r\n\r\n");foreach(var t in tweaks.Where(x=>x.Direct)){b.AppendLine(t.Name+": "+t.Read());if(t.Path!=null)try{using(var k=Registry.CurrentUser.OpenSubKey(t.Path,true))b.AppendLine("  Writable key handle: "+(k==null?"key absent; creation not tested":"available (no value written)"));}catch(Exception e){b.AppendLine("  Write access unavailable: "+e.Message);}}foreach(string path in new[]{Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),@".minecraft\options.txt"),Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),@"FortniteGame\Saved\Config\WindowsClient\GameUserSettings.ini")})try{b.AppendLine(Path.GetFileName(path)+": "+(File.Exists(path)?"found; "+new FileInfo(path).Length+" bytes; attributes="+File.GetAttributes(path):"not found"));}catch(Exception e){b.AppendLine(e.Message);}b.AppendLine("\r\nUser Run entries: "+Startup.Read().Count);b.AppendLine("nvidia-smi: "+(File.Exists(Path.Combine(Environment.SystemDirectory,"nvidia-smi.exe"))?"available":"not found"));b.AppendLine("\r\nNo security state is changed by this audit. Readability does not establish effective settings,\r\nanti-cheat acceptance, publisher approval or improved game performance.");diagnosticText.Text=b.ToString();Status("Access audit complete; no settings written.");}
 }
 public sealed class ResourceChart:Control {
  public ResourceSample[] Values=new ResourceSample[0];public ResourceChart(){DoubleBuffered=true;}
  protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var g=e.Graphics;g.DrawString("RECENT RESOURCE SAMPLES   /   CPU: blue   RAM: mint   /   0-100%",Font,Brushes.LightGray,12,8);using(var line=new Pen(Color.FromArgb(42,33,28)))for(int i=0;i<3;i++)g.DrawLine(line,12,35+i*30,Width-12,35+i*30);if(Values.Length<2)return;Draw(g,x=>x.Cpu,Color.CornflowerBlue);Draw(g,x=>x.Ram,Color.FromArgb(232,150,74));}
  void Draw(Graphics g,Func<ResourceSample,double> selector,Color color){using(var pen=new Pen(color,2)){PointF? last=null;for(int i=0;i<Values.Length;i++){double value=selector(Values[i]);if(double.IsNaN(value)){last=null;continue;}var next=new PointF(12+i*(Width-24f)/Math.Max(1,Values.Length-1),Height-12-(float)value/100*(Height-45));if(last.HasValue)g.DrawLine(pen,last.Value,next);last=next;}}}
 }
}












